 return hs

def compopts(k,kind):
 if kind=='star':return [(0,0,1),(1,1,k-1),(2,1,math.comb(k-1,2))]
 opts=[(0,0,1)]
 for j in range(1,k):
  for p in range(1,min(j,k-j)+1):opts.append((j,p,math.comb(j-1,p-1)*math.comb(k-j,p)))
