   if a>=qa:a,b=b,a
   if a<qa<=b:used.add((a,b-qa))
  if not used:return {'status':'impossible','iterations':iteration}
  outer.add(z3.Or(*[holes[ij] for ij in used]))
 return {'status':'limit','iterations':limit}

