 for u,v in H.edges:
  allows=[z3.And(mp[u]==i,mp[v]==j) if h is None else z3.And(mp[u]==i,mp[v]==j,z3.Not(h)) for i,j,h in terms]
  inner.add(z3.Implies(z3.And(active[u],active[v]),z3.Or(*allows)))
